'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float32Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float32Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `find` method', function test( t ) {
	var arr = new Float32Array( 2 );
	t.strictEqual( hasProp( arr, 'find' ), true, 'has property' );
	t.strictEqual( isFunction( arr.find ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.find.call( value, predicate );
		};
	}

	function predicate( v ) {
		return ( v > 2.0 );
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 10 );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.find( value );
		};
	}
});

tape( 'the method returns `undefined` if operating on an empty typed array', function test( t ) {
	var arr;
	var v;

	arr = new Float32Array();
	v = arr.find( predicate );

	t.strictEqual( v, void 0, 'returns expected value' );
	t.end();

	function predicate() {
		t.fail( 'should not be invoked' );
	}
});

tape( 'the method returns the first element which passes a test', function test( t ) {
	var arr;
	var v;

	arr = new Float32Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	v = arr.find( predicate );

	t.strictEqual( v, 3.0, 'returns expected value' );
	t.end();

	function predicate( val ) {
		return ( val > 2.0 );
	}
});

tape( 'the method returns `undefined` if all elements fail a test', function test( t ) {
	var arr;
	var v;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	v = arr.find( predicate );

	t.strictEqual( v, void 0, 'returns expected value' );
	t.end();

	function predicate( val ) {
		return ( val > 10.0 );
	}
});

tape( 'the method supports providing an execution context', function test( t ) {
	var ctx;
	var arr;
	var v;

	ctx = {
		'count': 0
	};
	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	v = arr.find( predicate, ctx );

	t.strictEqual( v, 3.0, 'returns expected value' );
	t.strictEqual( ctx.count, 3, 'returns expected value' );

	t.end();

	function predicate( val ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return ( val > 2.0 );
	}
});
